def shell(title, body, active = nil, prefix = "")
  nav = [["index.html", "Investigação"], ["freguesias/index.html", "Freguesias"], ["metodologia.html", "Metodologia"]].map { |url, label| "<a class=\"nav-link\" href=\"#{prefix}#{url}\">#{label}</a>" }.join
  <<~HTML
    <!doctype html><html lang="pt-PT"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Uma investigação de dados sobre o alojamento local em Lisboa."><title>#{h(title)} · AL em análise</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="#{prefix}assets/story.css"></head><body class="antialiased"><a class="skip-link" href="#conteudo">Saltar para o conteúdo</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="#{prefix}index.html"><span class="al-mark">AL</span><span><strong>Quantos alojamentos locais existem realmente em Lisboa?</strong></span></a><nav aria-label="Navegação principal">#{nav}</nav></div></header><div class="tile-rule"></div><main id="conteudo">#{body}</main><footer class="site-footer"><div class="wrap footer-grid"><span>Alojamento Local em Análise</span><span>Dados públicos · indicadores para verificação</span><a href="#{prefix}metodologia.html">Metodologia →</a></div></footer></body></html>
  HTML
end

def provenance(metadata, run_id, prefix = "")
  date = metadata.fetch("source_dates")
  "<div class=\"provenance\">Dados Airbnb: <strong>#{h(date['airbnb_snapshot_date'])}</strong> · registo descarregado: <strong>#{h(date['official_register_download_date'])}</strong> · <a href=\"#{prefix}runs/#{h(run_id)}/report.html\">relatório técnico</a></div>"
end

def home(summary, metadata, listings, freguesias, run_id, quotes)
  by = counts(listings)
  official = official_count(summary, run_id)
  total = summary["listings"].to_i
  estimate = summary["establishment_estimate"].to_i
  no = by["sem licença identificável"][:listings]
  repeated = by["licença repetida em várias localizações"][:listings]
  outside = by["licença oficial fora de Lisboa"][:listings]
  collapsed = total - estimate
  no_pct = (no.to_f / total * 100).round(1)
  top = freguesias.sort_by { |r| -r["listings"].to_i }.first(5)
  bars = top.map { |r| "<div class=\"compare-row\"><span>#{h(pretty(r['freguesia']))}</span><i style=\"--bar:#{(r['listings'].to_f / top.first['listings'].to_f * 100).round(1)}%\"></i><strong>#{n(r['listings'])}</strong></div>" }.join
  opening_quote = if quotes.empty?
    "<p class=\"opening-quote\">É um número que aparece repetidamente quando se fala de alojamento local em Lisboa.</p>"
  else
    "<div class=\"quote-strip\">#{quotes.sort_by { |q| q['sort_date'].to_s }.reverse.first(3).map { |q| "<article class=\"quote-item\"><div class=\"quote-date\">#{h(q['date'])}</div><blockquote>“#{h(q['excerpt'])}”</blockquote><cite>#{h(q['person'])} · <a href=\"#{h(q['url'])}\">#{h(q['source'])} ↗</a></cite></article>" }.join}</div>"
  end
  filled = (no.to_f / total * 40).round
  dots = (0...40).map { |i| "<i class=\"dot#{i < filled ? ' is-signal' : ''}\" aria-hidden=\"true\"></i>" }.join
  explain = lambda do |known, unknown|
    "<details class=\"meaning\"><summary>O que significa?</summary><div class=\"meaning-grid\"><div><b>O que sabemos</b><p>#{h(known)}</p></div><div><b>O que não sabemos</b><p>#{h(unknown)}</p></div></div></details>"
  end
  body = <<~HTML
    <section class="hero story-opening"><div class="wrap opening-inner"><h1 class="display">Quantos alojamentos locais existem realmente em Lisboa?</h1>#{opening_quote}<div class="hero-number"><span>~11 000</span><b>?</b></div><p class="opening-close">Fomos aos dados tentar perceber.</p></div></section>
    <section class="chapter source-chapter" id="investigacao"><div class="wrap"><div class="source-rail"><span class="source-label source-claims">O que se diz</span><span class="source-label source-official">Registo oficial</span><span class="source-label source-airbnb">Listagens de Airbnb</span></div><div class="source-numbers"><article><strong>~11 000</strong><p>número recorrente no debate público</p><a class="source-method-link" href="metodologia.html#o-que-se-diz">fontes e contexto ↗</a></article><article><strong>#{official ? n(official) : '—'}</strong><p><a href="#{h(metadata['source_urls']['official'])}">registos no concelho de Lisboa · RNAL ↗</a><br><small>registo de #{h(metadata['source_dates']['official_register_date'])}</small></p><a class="source-method-link" href="metodologia.html#registo-oficial">como contamos ↗</a></article><article><strong>#{n(estimate)}</strong><p>estimativa de estabelecimentos representados</p><p class="source-note"><a href="https://insideairbnb.com/lisbon/">#{n(total)} anúncios no snapshot · Inside Airbnb ↗</a><br><small>snapshot de #{h(metadata['source_dates']['airbnb_snapshot_date'])} · estimativa analítica, não contagem oficial</small></p><a class="source-method-link" href="metodologia.html#listagens-airbnb">como contamos ↗</a></article></div></div></section>
    <section class="chapter findings-chapter"><div class="wrap"><div class="eyebrow">05 · Sinais</div><h2 class="display display-medium">O que os dados revelam<br><em>Padrões que merecem atenção.</em></h2><div class="finding-story finding-unlicensed"><div class="finding-copy"><span class="signal-label">CONTAGEM</span><strong class="finding-number">#{n(no)}</strong><h3>sem licença identificável</h3><p>#{no_pct}% dos anúncios no snapshot.</p>#{explain.call('O anúncio não apresenta um número que consigamos reconhecer e normalizar como licença de AL.', 'Pode haver uma isenção, um campo vazio, uma alteração de registo ou um formato que não conseguimos interpretar.')}</div><div class="dot-field" role="img" aria-label="Campo proporcional: cerca de um quarto dos anúncios não tem licença identificável">#{dots}<span>#{no_pct}% dos anúncios</span></div></div><div class="finding-story finding-spatial"><div class="finding-copy"><span class="signal-label">SINAL</span><strong class="finding-number">#{n(repeated)}</strong><h3>licença repetida em diferentes localizações</h3><p>O mesmo número aparece associado a anúncios geograficamente separados.</p>#{explain.call('A licença normalizada surge em agrupamentos espaciais distintos.', 'Só com estes dados não sabemos se há reutilização, erro de localização, mudança de registo ou outra explicação.')}</div><div class="spatial-graphic" aria-label="Uma mesma licença ligada a duas localizações"><b>AL 12345</b><span class="spatial-line line-one"></span><span class="spatial-line line-two"></span><i class="place place-one">● Arroios</i><i class="place place-two">● Belém</i></div></div><div class="finding-story finding-outside"><div class="finding-copy"><span class="signal-label">SINAL</span><strong class="finding-number">#{n(outside)}</strong><h3>licença oficial fora de Lisboa</h3><p>O anúncio aparece no dataset de Lisboa, mas a licença identificada pertence oficialmente a outro município.</p>#{explain.call('A correspondência encontrada no RNAL tem outro município oficial.', 'Pode haver uma diferença de localização, de snapshot, de registo ou de qualidade dos dados. Não podemos concluir que o anúncio é ilegal.')}</div><div class="municipality-graphic" aria-label="O anúncio em Lisboa aponta para uma licença oficialmente registada noutro município"><span class="source-label source-airbnb">AIRBNB</span><b>Lisboa</b><i>AL 12345</i><span class="municipality-arrow">↓</span><span class="source-label source-official">RNAL</span><b>outro município</b></div></div></div><p class="notice-dark"><strong>Importante:</strong> estes são indicadores para verificação. Não demonstram, por si só, ilegalidade, culpa ou incumprimento.</p></section>
    <section class="chapter geography-chapter"><div class="wrap split"><div><div class="eyebrow">08 · Segundo acto</div><h2 class="display display-medium">E onde estão?</h2><p class="hero-dek">A pergunta muda de escala. Explore como os anúncios, as licenças e os sinais se distribuem pelas freguesias de Lisboa.</p><a class="story-link" href="freguesias/index.html">Explorar todas as freguesias →</a></div><div class="lisbon-schematic"><div class="tejo-block"></div><div class="districts">#{top.map { |r| "<span>#{h(pretty(r['freguesia']))}</span>" }.join}</div><small>contagens agregadas · sem coordenadas individuais</small></div></div><div class="compare">#{bars}</div></section>
    <section class="method-strip"><div class="wrap footer-grid"><h2>Ver os dados.<br>Reproduzir a análise.</h2><p>Cada run conserva datas, URLs e hashes. Os outputs públicos são agregados e não expõem identificadores, endereços ou coordenadas exatas.</p><a href="metodologia.html">Como calculámos isto →</a></div></section><div>#{provenance(metadata, run_id)}</div>
  HTML
  shell("Quantos alojamentos locais existem realmente em Lisboa?", body)
end

def home_legacy(summary, metadata, listings, freguesias, run_id, quotes)
  by = counts(listings); official = official_count(summary, run_id); no = by["sem licença identificável"][:listings]; repeated = by["licença repetida em várias localizações"][:listings]; outside = by["licença oficial fora de Lisboa"][:listings]
  top = freguesias.sort_by { |r| -r["listings"].to_i }.first(5)
  quote = quotes.empty? ? "<div class=\"empty-source\"><span class=\"quote-mark\">“</span><span>Arquivo editorial preparado para citações verificadas.</span><a href=\"metodologia.html#fontes\">Como tratamos as fontes →</a></div>" : quotes.map { |q| "<article class=\"quote-card\"><div class=\"eyebrow\">#{h(q['date'])}</div><blockquote>#{h(q['excerpt'])}</blockquote><p>#{h(q['person'])} · #{h(q['source'])}</p><a href=\"#{h(q['url'])}\">Fonte externa ↗</a></article>" }.join
  bars = top.map { |r| "<div class=\"compare-row\"><span>#{h(pretty(r['freguesia']))}</span><i style=\"--bar:#{(r['listings'].to_f / top.first['listings'].to_f * 100).round(1)}%\"></i><strong>#{n(r['listings'])}</strong></div>" }.join
  body = <<~HTML
    <section class="hero lisbon-tile"><div class="wrap hero-grid"><div><div class="eyebrow chip">Lisboa · uma investigação de dados</div><h1 class="display">Quantos alojamentos locais existem <em>realmente</em> em Lisboa?</h1><p class="hero-dek">É comum encontrar um número próximo dos <strong>11 mil</strong>. Mas registos, anúncios e estabelecimentos não são a mesma coisa.</p><p class="scroll-cue">↓ Desça para seguir a contagem</p></div><div class="hero-number"><span>11 000</span><b>?</b></div></div></section>
    <section class="chapter chapter-paper"><div class="wrap"><div class="eyebrow">01 · O que se diz</div><h2 class="display display-medium">O número aparece.<br><em>A pergunta fica.</em></h2><div class="quote-grid">#{quote}</div></div></section>
    <section class="chapter" id="investigacao"><div class="wrap"><div class="chapter-intro"><div><div class="eyebrow">02 · As três perspectivas</div><h2 class="display display-medium">O mesmo número.<br><em>Coisas diferentes.</em></h2></div><p>Antes de contar, precisamos de perceber o que cada fonte está a medir. A investigação cruza o discurso público, o registo oficial e os anúncios observados.</p></div><div class="source-grid"><article class="source-card"><div class="eyebrow">O que se diz</div><div class="source-symbol">“</div><h3>Notícias<br>e declarações</h3><p>Um enquadramento editorial, não uma contagem produzida por esta investigação.</p></article><article class="source-card"><div class="eyebrow">Registo oficial</div><div class="source-symbol">↓</div><h3>#{official ? n(official) : '—'}</h3><p>registos no concelho de Lisboa</p><small>Turismo de Portugal · RNAL</small></article><article class="source-card platform"><div class="eyebrow">Airbnb</div><div class="source-symbol">●</div><h3>#{n(summary['listings'])}</h3><p>anúncios no snapshot</p><small>Inside Airbnb · #{h(metadata['source_dates']['airbnb_snapshot_date'])}</small></article></div></div></section>
    <section class="chapter"><div class="wrap split"><div class="sticky-copy"><div class="eyebrow">03 · O primeiro problema</div><h2 class="display display-small">#{n(summary['listings'])} anúncios não são #{n(summary['listings'])} alojamentos.</h2><p>O mesmo estabelecimento pode aparecer várias vezes. A análise agrupa anúncios com a mesma licença e na mesma localização, mas mantém separados os sinais que merecem investigação.</p></div><div class="diagram"><div class="diagram-label">Exemplo sintético · uma licença, vários anúncios</div><div class="listing-stack"><span>Quarto 1 <b>AL 67890</b></span><span>Quarto 2 <b>AL 67890</b></span><span>Quarto 3 <b>AL 67890</b></span></div><div class="diagram-arrow">↓</div><div class="establishment"><b>AL 67890</b><strong>1 provável estabelecimento?</strong><small>3 anúncios Airbnb</small></div><p class="caption">Uma estimativa analítica, não uma confirmação de identidade física.</p></div></div></section>
    <section class="chapter chapter-paper"><div class="wrap"><div class="eyebrow">04 · O cruzamento</div><h2 class="display display-medium">Dois universos.<br><em>Uma ligação imperfeita.</em></h2><div class="cross-grid"><div class="cross-column"><span class="eyebrow">Turismo de Portugal</span><div>licença reconhecida</div><div>licença repetida</div><div>concelho oficial</div></div><div class="cross-lines">←────→<br>←─┬──→<br>  └──→</div><div class="cross-column platform-border"><span class="eyebrow">Airbnb</span><div>anúncio</div><div>quarto 1 · quarto 2</div><div>localização observada</div></div></div><p class="hero-dek">O número de licença é uma chave útil, mas não resolve sozinho a diferença entre anúncio, unidade e estabelecimento.</p></div></section>
    <section class="chapter chapter-dark"><div class="wrap"><div class="dark-intro"><div><div class="eyebrow light">05 · Mas há anúncios que não encaixam</div><h2 class="display display-medium">Sinais para investigar.<br><em>Não conclusões automáticas.</em></h2></div><p>Ao cruzar Airbnb e RNAL, aparecem diferenças que precisam de confirmação. A linguagem é deliberadamente conservadora.</p></div><div class="finding-grid">#{[[no, 'Sem licença identificável', 'O anúncio não apresenta um número que consigamos reconhecer e normalizar como licença de AL.'], [repeated, 'Licença repetida em diferentes localizações', 'O mesmo número aparece associado a anúncios geograficamente separados.'], [outside, 'Licença registada fora de Lisboa', 'O anúncio está no dataset de Lisboa, mas o registo identificado pertence a outro concelho.']].map { |value, title, text| "<article class=\"finding\"><div class=\"finding-number\">#{n(value)}</div><div><div class=\"finding-mark\">#{title.start_with?('Sem') ? '?' : title.start_with?('Licença repetida') ? '↻' : '⌖'}</div><h3>#{title}</h3><p>#{text}</p></div></article>" }.join}</div><p class="notice-dark"><strong>Importante:</strong> são sinais para verificação. Não demonstram, por si só, ilegalidade, culpa ou incumprimento.</p></div></section>
    <section class="chapter"><div class="wrap"><div class="eyebrow">06 · Construir uma estimativa</div><h2 class="display display-medium">Em vez de escolher um número,<br><em>mostramos como chegamos até ele.</em></h2><div class="waterfall"><div class="water-row"><span>Anúncios Airbnb</span><i style="--bar:100%"></i><strong>#{n(summary['listings'])}</strong></div><div class="water-row"><span>Agrupar categorias colapsáveis</span><i style="--bar:#{(summary['establishment_estimate'].to_f / summary['listings'].to_f * 100).round(1)}%"></i><strong>↓</strong></div><div class="water-row result"><span><b>Estabelecimentos estimados</b><small>metodologia #{h(summary['methodology_version'])}</small></span><i style="--bar:#{(summary['establishment_estimate'].to_f / summary['listings'].to_f * 100).round(1)}%"></i><strong>#{n(summary['establishment_estimate'])}</strong></div></div><p class="caption">Só as categorias previstas na metodologia como plausíveis para um mesmo estabelecimento são colapsadas.</p></div></section>
    <section class="chapter chapter-paper"><div class="wrap split"><div><div class="eyebrow">07 · E onde estão?</div><h2 class="display display-medium">A cidade<br><em>não é uniforme.</em></h2><p class="hero-dek">Explore os resultados por freguesia. Os outputs publicados são agregados e não expõem coordenadas individuais.</p><a href="freguesias/index.html">Explorar todas as freguesias →</a></div><div class="lisbon-schematic"><div class="tejo-block"></div><div class="districts">#{top.map { |r| "<span>#{h(r['freguesia'])}</span>" }.join}</div><small>contagens agregadas</small></div></div><div class="compare">#{bars}</div></div></section>
    <section class="chapter"><div class="wrap"><div class="eyebrow">08 · Então, quantos?</div><h2 class="display display-medium">Depende da pergunta<br><em>que estamos a fazer.</em></h2><div class="conclusion-grid"><div><div class="eyebrow">O número citado</div><strong>~11 000</strong><p>Um valor recorrente no debate público.</p></div><div><div class="eyebrow">O que observamos</div><strong>#{n(summary['listings'])}</strong><p>Anúncios no snapshot do Inside Airbnb.</p></div><div><div class="eyebrow">A estimativa</div><strong>#{n(summary['establishment_estimate'])}</strong><p>Estabelecimentos estimados pela metodologia.</p></div></div><p class="final-line">Não existe um único número que responda a todas as perguntas.</p></div></section>
    <section class="method-strip"><div class="wrap footer-grid"><h2>Ver os dados.<br>Reproduzir a análise.</h2><p>Cada run conserva datas, URLs e hashes. Os outputs públicos são agregados e não expõem identificadores, endereços ou coordenadas exatas.</p><a href="metodologia.html">Abrir metodologia →</a></div></section><div>#{provenance(metadata, run_id)}</div>
  HTML
  shell("Quantos alojamentos locais existem realmente em Lisboa?", body)
end

def freguesia_page(name, row, grouped, all_rows, metadata, run_id)
  raw_name = name; name = pretty(name); total = row["listings"].to_i; current = grouped[raw_name] || counts([]); top = all_rows.sort_by { |r| -r["listings"].to_i }.first(7)
  composition = LABELS.keys.filter_map { |key| data = current[key]; data && data[:listings] > 0 ? "<div class=\"composition-row\"><span>#{h(LABELS[key])}</span><strong>#{n(data[:listings])}</strong></div>" : nil }.join
  table = LABELS.keys.filter_map { |key| data = current[key]; data ? "<tr data-name=\"#{h(LABELS[key])}\"><th>#{h(LABELS[key])}</th><td>#{n(data[:listings])}</td><td>#{n(data[:licences])}</td></tr>" : nil }.join
  bars = top.map { |r| "<div class=\"compare-row #{r['freguesia'] == raw_name ? 'current' : ''}\"><span>#{h(pretty(r['freguesia']))}</span><i style=\"--bar:#{(r['listings'].to_f / top.first['listings'].to_f * 100).round(1)}%\"></i><strong>#{n(r['listings'])}</strong></div>" }.join
  body = <<~HTML
    <section class="district-hero lisbon-tile"><div class="wrap district-grid"><div><a href="../index.html">← Lisboa</a><div class="eyebrow chip">Freguesia · análise local</div><h1 class="display">O alojamento local<br><em>em #{h(name)}.</em></h1><p class="hero-dek">Uma leitura local dos anúncios observados, das licenças identificadas e dos sinais que merecem verificação.</p></div><div class="district-mark"><span>#{h(name.split.map { |w| w[0] }.join)}</span><b>#{n(total)}</b></div></div></section>
    <section class="chapter chapter-paper"><div class="wrap"><div class="eyebrow">01 · A freguesia em números</div><div class="metric-grid"><div class="metric platform"><div class="metric-value">#{n(total)}</div><div class="metric-label">anúncios Airbnb</div></div><div class="metric official"><div class="metric-value">#{n(row['establishments_estimate'])}</div><div class="metric-label">estabelecimentos estimados</div></div><div class="metric official"><div class="metric-value">#{n(current.values.sum { |v| v[:licences] })}</div><div class="metric-label">licenças identificáveis</div></div></div></div></section>
    <section class="chapter"><div class="wrap split"><div class="sticky-copy"><div class="eyebrow">02 · Composição</div><h2 class="display display-small">O que compõe<br>#{n(total)} anúncios?</h2><p>As categorias seguem a classificação da pipeline. “Sem licença identificável” não é uma conclusão de ilegalidade.</p></div><div class="composition">#{composition}</div></div></section>
    <section class="chapter chapter-dark"><div class="wrap split"><div><div class="eyebrow light">03 · Distribuição espacial</div><h2 class="display display-small">Onde estão<br>os anúncios?</h2><p>Os outputs publicados preservam a privacidade e não expõem coordenadas individuais. Mostramos por isso a composição agregada.</p></div><div class="map-placeholder"><div class="map-grid">#{Array.new(42) { "<i></i>" }.join}</div><span>distribuição agregada<br>sem coordenadas públicas</span></div></div></section>
    <section class="chapter chapter-paper"><div class="wrap"><div class="eyebrow">04 · Comparação com Lisboa</div><h2 class="display display-small">Uma leitura de escala,<br><em>não um ranking.</em></h2><div class="compare">#{bars}</div></div></section>
    <section class="chapter"><div class="wrap"><div class="eyebrow">05 · Explorar os dados de #{h(name)}</div><h2 class="display display-small">Uma camada mais analítica.</h2><div class="data-controls"><button class="filter is-active" data-filter="all">Todas</button>#{LABELS.values.map { |label| "<button class=\"filter\" data-filter=\"#{h(label)}\">#{h(label.split.first(2).join(' '))}</button>" }.join}</div><div class="table-wrap"><table><thead><tr><th>Categoria</th><th>Anúncios</th><th>Licenças</th></tr></thead><tbody>#{table}</tbody></table></div><p class="caption">Consulte os <a href="../../runs/#{h(run_id)}/">ficheiros agregados do snapshot</a> e a <a href="../../metodologia.html">metodologia completa</a>.</p></div></section><div>#{provenance(metadata, run_id, '../../')}</div><script>document.querySelectorAll('.filter').forEach(function(b){b.onclick=function(){document.querySelectorAll('.filter').forEach(function(x){x.classList.remove('is-active')});b.classList.add('is-active');document.querySelectorAll('tbody tr').forEach(function(r){r.hidden=b.dataset.filter!='all'&&r.dataset.name!=b.dataset.filter})}})</script>
  HTML
  shell("O alojamento local em #{name}", body, "", "../../")
end

def freguesias_index(rows, metadata, run_id)
  cards = rows.sort_by { |r| -r["listings"].to_i }.map { |r| "<a class=\"district-card\" href=\"#{slug(r['freguesia'])}/index.html\"><span class=\"shape-glyph\">#{h(pretty(r['freguesia']).split.map { |w| w[0] }.join)}</span><span class=\"eyebrow\">#{h(pretty(r['freguesia']))}</span><strong>#{n(r['listings'])}</strong><small>anúncios · #{n(r['establishments_estimate'])} estimados</small></a>" }.join
  shell("Freguesias de Lisboa", "<section class=\"district-index-hero lisbon-tile\"><div class=\"wrap\"><div class=\"eyebrow chip\">Lisboa · #{rows.length} freguesias</div><h1 class=\"display\">E onde <em>estão?</em></h1><p class=\"hero-dek\">Uma leitura por freguesia dos anúncios observados e dos estabelecimentos estimados.</p></div></section><section class=\"chapter chapter-paper\"><div class=\"wrap\"><div class=\"district-list\">#{cards}</div></div></section><div>#{provenance(metadata, run_id, '../')}</div>", "", "../")
end

def methodology(metadata, summary, run_id, quotes = [])
  quotes = JSON.parse(File.read(QUOTES)) if quotes.empty? && File.exist?(QUOTES)
  total = summary['listings'].to_i
  estimate = summary['establishment_estimate'].to_i
  collapsed = total - estimate
  quote_items = quotes.first(3).map { |q| "<article class=\"method-quote\"><div class=\"quote-date\">#{h(q['date'])}</div><blockquote>“#{h(q['excerpt'])}”</blockquote><cite>#{h(q['person'])} · <a href=\"#{h(q['url'])}\">#{h(q['source'])} ↗</a></cite></article>" }.join
  quote_items = "<p>Não foram configuradas citações editoriais para este run.</p>" if quote_items.empty?
  methodology_story = <<~HTML
    <section class="chapter chapter-airbnb"><div class="wrap split"><div class="sticky-copy"><div class="eyebrow source-airbnb">01 · Airbnb</div><h2 class="display display-small">#{n(total)} anúncios<br><em>não são #{n(total)} estabelecimentos.</em></h2><p>Um anúncio pode ser uma unidade, um quarto ou parte de um estabelecimento.</p></div><div class="listing-example" aria-label="Exemplo de anúncios Airbnb que podem representar um estabelecimento"><div class="diagram-label">Exemplo sintético · Airbnb</div><div class="listing-stack"><span>Apartamento <b>AL 12345</b></span><span>Quarto 1 <b>AL 67890</b></span><span>Quarto 2 <b>AL 67890</b></span><span>Quarto 3 <b>AL 67890</b></span></div><div class="collapse-arrow">↓</div><div class="establishment"><b>AL 67890</b><strong>3 anúncios → 1 provável estabelecimento</strong><small>o agrupamento é analítico</small></div></div></div></section>
    <section class="chapter matching-chapter"><div class="wrap"><div class="eyebrow">02 · O cruzamento</div><h2 class="display display-medium">Licenças são a ponte<br><em>entre os dois universos.</em></h2><div class="matching-graphic" aria-label="O RNAL é ligado aos anúncios Airbnb através do número de licença"><div class="matching-side official-side"><span class="source-label source-official">Turismo de Portugal · RNAL</span><b>AL 12345</b><b>AL 67890</b></div><div class="matching-arrows"><span>←────→</span><span>←──┬─→</span><span>　 └─→</span></div><div class="matching-side airbnb-side"><span class="source-label source-airbnb">Airbnb</span><b>anúncio</b><b>quarto 1 · quarto 2 · quarto 3</b></div></div><p class="source-thesis">Tentamos encontrar no registo oficial as licenças que aparecem nos anúncios. O resultado é uma leitura de sinais, não uma sentença.</p></div></section>
    <section class="chapter estimate-chapter"><div class="wrap"><div class="eyebrow">03 · Interpretação</div><h2 class="display display-medium">Como chegamos de<br><em>#{n(total)} a #{n(estimate)}?</em></h2><p class="estimate-intro">A nossa contagem começa nos anúncios e aplica apenas a deduplicação prevista na metodologia.</p><div class="estimate-steps"><div><span>1</span><strong>#{n(total)}</strong><p>anúncios Airbnb</p></div><div><span>2</span><strong>− #{n(collapsed)}</strong><p>duplicações colapsáveis<br><small>anúncios múltiplos / mesma localização</small></p></div><div class="estimate-result"><span>3</span><strong>#{n(estimate)}</strong><p>estabelecimentos estimados</p></div></div><p class="caption">Esta é uma estimativa analítica. Licenças ausentes ou repetidas em locais diferentes não são automaticamente fundidas.</p></div></section>
  HTML
  body = "<section class=\"method-hero lisbon-tile\"><div class=\"wrap\"><div class=\"eyebrow chip\">Proveniência · transparência</div><h1 class=\"display\">Como contamos<br><em>o que contamos.</em></h1><p class=\"hero-dek\">A narrativa é uma camada sobre uma análise versionada. O método completo continua disponível para leitura e reprodução.</p></div></section><section class=\"chapter chapter-paper\"><div class=\"wrap method-grid\"><div><div class=\"eyebrow\">O que os dados significam</div><h2 class=\"display display-small\">Três contagens legítimas.</h2></div><div class=\"method-copy\"><p><strong>Registos oficiais</strong> são entradas no RNAL filtradas pelo concelho de Lisboa.</p><p><strong>Anúncios Airbnb</strong> são observações do snapshot do Inside Airbnb. Um anúncio pode representar uma unidade, um quarto ou parte de um estabelecimento.</p><p><strong>Estabelecimentos estimados</strong> resultam da classificação e deduplicação da pipeline. São uma estimativa analítica.</p></div></div></section><section class=\"chapter method-source-section\" id=\"o-que-se-diz\"><div class=\"wrap\"><div class=\"eyebrow\">O que se diz</div><h2 class=\"display display-small\">A contagem pública<br><em>também tem uma história.</em></h2><div class=\"method-quotes\">#{quote_items}</div><p class=\"method-copy\">Estas declarações ajudam a explicar de onde vem o número público. Não são uma contagem produzida por esta investigação.</p></div></section><section class=\"chapter method-source-section\" id=\"registo-oficial\"><div class=\"wrap method-grid\"><div><div class=\"eyebrow\">Registo oficial</div><h2 class=\"display display-small\">Como contamos<br><em>o RNAL.</em></h2></div><div class=\"method-copy\"><p>Descarregamos o registo nacional de alojamento local e contamos as entradas cujo campo <strong>Concelho</strong> corresponde a <strong>Lisboa</strong>.</p><p>Este número mede registos oficiais no município. Não mede anúncios ativos nem garante que cada registo corresponda hoje a um estabelecimento em funcionamento.</p><p><a href=\"#{h(metadata['source_urls']['official'])}\">Fonte oficial / RNAL ↗</a><br><small>registo de #{h(metadata['source_dates']['official_register_date'])} · descarregado em #{h(metadata['source_dates']['official_register_download_date'])}</small></p></div></div></section><section class=\"chapter method-source-section\" id=\"listagens-airbnb\"><div class=\"wrap method-grid\"><div><div class=\"eyebrow\">Listagens de Airbnb</div><h2 class=\"display display-small\">Como contamos<br><em>os anúncios.</em></h2></div><div class=\"method-copy\"><p>Usamos o snapshot público do Inside Airbnb para Lisboa. Neste run, são <strong>#{n(total)} anúncios</strong>, recolhidos em #{h(metadata['source_dates']['airbnb_snapshot_date'])}.</p><p>Um anúncio pode ser uma unidade, um quarto ou parte de um estabelecimento. A estimativa de #{n(estimate)} é construída depois, aplicando apenas a deduplicação prevista na metodologia.</p><p><a href=\"https://insideairbnb.com/lisbon/\">Inside Airbnb · Lisboa ↗</a><br><small>snapshot de #{h(metadata['source_dates']['airbnb_snapshot_date'])}</small></p></div></div></section>#{methodology_story}<section class=\"chapter\" id=\"fontes\"><div class=\"wrap method-grid\"><div><div class=\"eyebrow\">Fontes e run</div><h2 class=\"display display-small\">Reproduzir é seguir as datas.</h2></div><div class=\"method-copy\"><dl><dt>Run</dt><dd>#{h(run_id)}</dd><dt>Airbnb</dt><dd>#{h(metadata['source_dates']['airbnb_snapshot_date'])} · <a href=\"#{h(metadata['source_urls']['airbnb'])}\">Inside Airbnb ↗</a></dd><dt>Registo</dt><dd>descarregado em #{h(metadata['source_dates']['official_register_download_date'])} · <a href=\"#{h(metadata['source_urls']['official'])}\">Turismo de Portugal / ArcGIS ↗</a></dd><dt>Versões</dt><dd>metodologia #{h(summary['methodology_version'])} · análise #{h(metadata['analysis_version'])}</dd></dl><p>Os outputs públicos são agregados: não incluem IDs, URLs, nomes, endereços, coordenadas exatas, valores de licença originais ou texto arbitrário das fontes.</p></div></div></section><section class=\"chapter chapter-dark\"><div class=\"wrap method-grid\"><div><div class=\"eyebrow light\">Linguagem e limites</div><h2 class=\"display display-small\">Sinais, não sentenças.</h2></div><div class=\"method-copy\"><p>“Sem licença identificável” significa que não foi possível reconhecer e normalizar uma licença no anúncio, não que o alojamento seja ilegal.</p><p>Uma licença repetida em localizações distintas é um padrão para verificação. Uma licença registada fora de Lisboa é uma divergência entre o local observado e o concelho oficial.</p></div></div></section><div>#{provenance(metadata, run_id)}</div>"
  shell("Metodologia e proveniência", body)
end

